a:2:{s:10:"custom_css";s:4871:"/* TM Home page 1061 — layout hooks matching Main.dc.html / site.css */
.elementor-page-1061 .tm-hero {
  padding-top: 64px;
  padding-bottom: 72px;
}
.elementor-page-1061 .tm-hero > .e-con-inner {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  gap: 56px;
  align-items: center;
}
.elementor-page-1061 .tm-hero > .e-con-inner > .tm-hero-copy,
.elementor-page-1061 .tm-hero > .e-con-inner > .tm-hp-hero-visual {
  width: 100% !important;
  max-width: none !important;
  min-width: 0;
}
.elementor-page-1061 .tm-hero-copy {
  align-items: flex-start;
}
.elementor-page-1061 .tm-hero-visual,
.elementor-page-1061 .tm-hp-hero-visual {
  position: relative;
  min-height: 420px;
}
.elementor-page-1061 .tm-hero-visual .elementor-widget-image img,
.elementor-page-1061 .tm-hp-hero-visual .elementor-widget-image img {
  border-radius: 12px;
  background: #e8eef4;
}
.elementor-page-1061 .tm-hero-trust {
  margin-top: 28px;
  padding-top: 24px;
  border-top: 1px solid #dedede;
  width: 100%;
}
.elementor-page-1061 .tm-eyebrow .elementor-heading-title {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  font-weight: 700;
  color: #0b2545;
  margin-bottom: 12px;
}
.elementor-page-1061 .tm-eyebrow .elementor-heading-title::before {
  content: "";
  width: 24px;
  height: 3px;
  border-radius: 2px;
  background: #54a3d8;
  flex: none;
}
.elementor-page-1061 .tm-eyebrow-inv .elementor-heading-title {
  color: #81bbe1;
}
.elementor-page-1061 .tm-eyebrow-inv .elementor-heading-title::before {
  background: #ffcc00;
}
.elementor-page-1061 .tm-section {
  padding-top: 88px;
  padding-bottom: 88px;
}
.elementor-page-1061 .tm-section-page {
  background: #f4f7fa;
}
.elementor-page-1061 .tm-section-navy {
  background: #0b2545;
  color: #fff;
}
.elementor-page-1061 .tm-section-navy .elementor-heading-title,
.elementor-page-1061 .tm-section-navy .elementor-widget-text-editor {
  color: #fff;
}
.elementor-page-1061 .tm-section-navy .elementor-widget-text-editor p {
  color: rgba(255, 255, 255, 0.84);
}
.elementor-page-1061 .tm-usp-grid > .e-con-inner {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 16px;
}
.elementor-page-1061 .tm-usp-grid .elementor-icon-box-wrapper {
  background: #fff;
  border: 1px solid #dedede;
  border-radius: 8px;
  padding: 20px;
  height: 100%;
}
.elementor-page-1061 .tm-cat-grid > .e-con-inner {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 16px;
}
.elementor-page-1061 .tm-cat-grid .elementor-icon-box-wrapper {
  border: 1px solid #dedede;
  border-radius: 8px;
  padding: 20px;
  height: 100%;
  background: #fff;
}
.elementor-page-1061 .tm-cat-accent .elementor-icon-box-wrapper {
  background: #0b2545;
  border-color: #0b2545;
}
.elementor-page-1061 .tm-online > .e-con-inner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 48px;
  align-items: center;
}
.elementor-page-1061 .tm-split-visual .elementor-widget-image img {
  border-radius: 12px;
  box-shadow: 0 24px 48px -24px rgba(11, 37, 69, 0.45);
}
.elementor-page-1061 .tm-steps > .e-con-inner {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 24px;
}
.elementor-page-1061 .tm-steps .elementor-icon-box-wrapper {
  text-align: center;
  padding: 16px;
}
.elementor-page-1061 .tm-reviews > .e-con-inner {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.4fr);
  gap: 40px;
  align-items: start;
}
.elementor-page-1061 .tm-review-cards > .e-con-inner {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
.elementor-page-1061 .tm-faq > .e-con-inner {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  gap: 48px;
  align-items: start;
}
.elementor-page-1061 .tm-cta {
  background: #e8eef4;
  border-radius: 12px;
  padding: 48px 40px;
  text-align: center;
}
@media (max-width: 1024px) {
  .elementor-page-1061 .tm-hero > .e-con-inner,
  .elementor-page-1061 .tm-online > .e-con-inner,
  .elementor-page-1061 .tm-faq > .e-con-inner,
  .elementor-page-1061 .tm-reviews > .e-con-inner {
    grid-template-columns: minmax(0, 1fr);
  }
  .elementor-page-1061 .tm-usp-grid > .e-con-inner {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .elementor-page-1061 .tm-cat-grid > .e-con-inner {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .elementor-page-1061 .tm-steps > .e-con-inner {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 767px) {
  .elementor-page-1061 .tm-usp-grid > .e-con-inner,
  .elementor-page-1061 .tm-cat-grid > .e-con-inner,
  .elementor-page-1061 .tm-steps > .e-con-inner,
  .elementor-page-1061 .tm-review-cards > .e-con-inner {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .elementor-page-1061 .tm-section {
    padding-top: 56px;
    padding-bottom: 56px;
  }
}
